type OptionKey = "A" | "B" | "C" | "D";
type Option = { key: OptionKey; text: string };
const subjectNames = ["Mathematics", "Physics", "Chemistry", "Biology", "Use of English", "Literature in English"] as const;
const formatTime = (seconds: number) => `${Math.floor(seconds / 60).toString().padStart(2, "0")}:${(seconds % 60).toString().padStart(2, "0")}`;
const recorderMimeCandidates = {
  video: ["video/webm;codecs=vp8", "video/webm;codecs=vp8,opus", "video/webm"],
  audio: ["audio/webm;codecs=opus", "audio/webm", "audio/ogg;codecs=opus", "audio/ogg"],
} as const;
function createCompatibleRecorder(stream: MediaStream, mediaType: "video" | "audio") {
  if (typeof MediaRecorder === "undefined") return null;
  const mimeType = recorderMimeCandidates[mediaType].find(candidate => typeof MediaRecorder.isTypeSupported !== "function" || MediaRecorder.isTypeSupported(candidate));
  const bitrateOptions = mediaType === "video" ? { videoBitsPerSecond: 180_000, audioBitsPerSecond: 48_000 } : { audioBitsPerSecond: 48_000 };
  try {
    return mimeType ? new MediaRecorder(stream, { mimeType, ...bitrateOptions }) : new MediaRecorder(stream, bitrateOptions);
  } catch {
    try { return new MediaRecorder(stream, bitrateOptions); } catch { return null; }
  }
}
