  const activeAttemptIdRef = useRef<number | null>(null);
  const recordingsStoppedRef = useRef(false);
  const warningLockRef = useRef<Record<string, number>>({});
  const review = trpc.school.studentJambAttemptReview.useQuery({ attemptId: reviewAttemptId ?? 0 }, { enabled: Boolean(reviewAttemptId) });
  const start = trpc.school.startJambAttempt.useMutation({ onSuccess: value => { activeAttemptIdRef.current = value.attempt.id; recordingsStoppedRef.current = false; setExamToStart(null); setActiveExam(value.exam); setActiveAttempt(value.attempt); setAnswers({}); setCurrent(0); setResult(null); setRemaining(value.exam.durationMinutes * 60); }, onError: error => toast.error(error.message) });
