  const submit = trpc.school.submitJambAttempt.useMutation({ onSuccess: value => { const attemptId = activeAttempt?.id ?? activeAttemptIdRef.current; if (attemptId) void liveEnd.mutate({ attemptId }); stopRecordings(attemptId); activeAttemptIdRef.current = null; setResult(value); setActiveExam(null); setActiveAttempt(null); void attempts.refetch(); toast.success("JAMB practice submitted successfully"); }, onError: error => toast.error(error.message) });
  const visibleExams = (exams.data ?? []).filter(exam => exam.subjectName === subject);
