          const current = recorderRefs.current; current.startedAt = Date.now(); current.videoChunks = []; current.audioChunks = [];
          if (videoTrack) { current.video = createCompatibleRecorder(new MediaStream([videoTrack]), "video"); if (current.video) { current.video.ondataavailable = event => { if (event.data.size) current.videoChunks.push(event.data); }; current.video.start(1000); } }
          if (audioTrack) { current.audio = createCompatibleRecorder(new MediaStream([audioTrack]), "audio"); if (current.audio) { current.audio.ondataavailable = event => { if (event.data.size) current.audioChunks.push(event.data); }; current.audio.start(1000); } }
